{
  "items": [
    {
      "name": "MvPolynomial.degreeOf_coeff_finSuccEquiv",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : CommSemiring R] {n : ℕ} (p : MvPolynomial (Fin (n + 1)) R) (j : Fin n) (i : ℕ),\n  MvPolynomial.degreeOf j (((MvPolynomial.finSuccEquiv R n) p).coeff i) ≤ MvPolynomial.degreeOf j.succ p"
    },
    {
      "name": "MvPolynomial.degreeOf_C_mul_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R) (i : σ) (c : R),\n  MvPolynomial.degreeOf i (MvPolynomial.C c * p) ≤ MvPolynomial.degreeOf i p"
    },
    {
      "name": "MvPolynomial.degreeOf_mul_C_le",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (p : MvPolynomial σ R) (i : σ) (c : R),\n  MvPolynomial.degreeOf i (p * MvPolynomial.C c) ≤ MvPolynomial.degreeOf i p"
    },
    {
      "name": "MvPolynomial.degreeOf_mul_X_self",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (j : σ) (f : MvPolynomial σ R),\n  MvPolynomial.degreeOf j (f * MvPolynomial.X j) ≤ MvPolynomial.degreeOf j f + 1"
    },
    {
      "name": "MvPolynomial.monomial_le_degreeOf",
      "module_name": "Mathlib.Algebra.MvPolynomial.Degrees",
      "kind": "theorem",
      "type": "∀ {R : Type u} {σ : Type u_1} [inst : CommSemiring R] (i : σ) {f : MvPolynomial σ R} {m : σ →₀ ℕ},\n  m ∈ f.support → m i ≤ MvPolynomial.degreeOf i f"
    }
  ]
}
